head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.arrPar = [];

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS30600.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 종료 처리(현재 처리 없음)
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function() {
    scwin.displayGrid(""); // 상세 그리드 전체 숨김

    // 콤보 세팅.
    await scwin.setCombo();

    // 기본값 세팅
    scwin.setDefaultVal();

    // 조회조건의 기간 체크
    $c.date.compareFromToDate(ipt_fromStdCdApplDd, ipt_toStdCdApplDd, ["신청일 시작일자", "신청일 종료일자"], "yyyyMMdd");

    // 조회조건 영역 엔터키 치면 자동 조회되도록 SET
    $c.win.setEnterKeyEvent(tbl_search, scwin.btn_search_onclick);
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_List_onrowindexchange
 * @description 그리드 row변경 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} oldRow 이전 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_onrowindexchange = async function (rowIndex, oldRow) {
    try {
        if (rowIndex < 0) {
            return;
        }

        const stdCdApplContnTpCd = dlt_searchList.getCellData(rowIndex, "stdCdApplContnTpCd");
        // 상품구분에따른 그리드를 display 하고..
        scwin.displayGrid(stdCdApplContnTpCd);

        // 상세조회
        await scwin.searchDetail(stdCdApplContnTpCd, rowIndex);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS30600.grd_List_onrowindexchange" });
    }
};

/**
 * @method
 * @name btn_search_onclick
 * @description 조회 버튼 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_search_onclick = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS30600.btn_search_onclick" });
    }
};

/**
 * @method
 * @name txb_ISU_NM_onkeyup
 * @description 한글종목명 키업 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISU_NM_onkeyup = function (e) {
    try {
        scwin.delSpecialCharPartial(txb_ISU_NM);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS30600.txb_ISU_NM_onkeyup" });
    }
};

/**
 * @method
 * @name cmb_STD_CD_APPL_CONTN_TP_CD_onchange
 * @description 상품구분 변경 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cmb_STD_CD_APPL_CONTN_TP_CD_onchange = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS30600.cmb_STD_CD_APPL_CONTN_TP_CD_onchange" });
    }
};

/**
 * @method
 * @name btn_prcnm_onclick
 * @description 처리자조회 버튼 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_prcnm_onclick = async function() {
    try {
        if (dlt_searchList.getRowPosition() < 0) return; // 목록 행 미선택
        txb_param1.setValue(dlt_searchList.getCellData(dlt_searchList.getRowPosition(), "stdCd"));
        txb_param2.setValue("");

        await scwin.openInsPopup("", "", "ULDINS93300", "표준코드 처리자 조회", "620", "420");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS30600.btn_prcnm_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    // 데이터셋 초기화
    scwin.initDs("search");

    // 조회조건 체크.
    if (!await scwin.chkValid("search")) {
        return;
    }

    const sbmOptions = {
        id: "sbmSearchList",
        action: "/api/isin/api/srchGrp/autoChgSrch/autoChgSrchList-select",
        method: "get",
        ref: "dma_searchList",
        target: "dlt_searchList=body",
        gridview: "grd_List|focus"
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    if (sbmRtn && sbmRtn.skipped) return;
    tbx_TotalCnt.setValue(dlt_searchList.getRowCount());
};

/**
 * @method
 * @name searchDetail
 * @description 상세조회 — 선택 행의 상품구분(01 채권·02 주권·03 수익증권·04 신주인수권증권·05 신주인수권증서·06 유가증권예탁증서·07 전자단기사채/CP·09 양도성예금증서·10 주식워런트·11 ELS/DLS·12 ETN·13 투자계약증권)에 맞는 상세 API 를 호출해 해당 그리드에 바인딩
 * @param {String} pGubun 상품구분코드
 * @param {Number} rowIndex 목록 선택 행
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchDetail = async function (pGubun, rowIndex) {
    // 데이터셋 초기화
    scwin.initDs("searchDetail");
    const detail = scwin.getDetailInfo(pGubun);
    if ($c.util.isEmpty(detail)) return;

    // 조회조건 세팅
    dma_searchDtl.set("param01", dlt_searchList.getCellData(rowIndex, "stdCd"));
    dma_searchDtl.set("param02", dlt_searchList.getCellData(rowIndex, "cnt"));

    const sbmOptions = {
        id : "sbmSearchDtl" + pGubun,
        action : "/api/isin/api/srchGrp/autoChgSrch/" + detail.api + "-select",
        method : "get",
        ref : "dma_searchDtl",
        target : "dlt_dtlList" + pGubun + "=body",
        gridview : "grd_DtlList" + pGubun
    };
    await $c.sbm.executeDynamic(sbmOptions);
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCombo
 * @description 콤보박스 만들기
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCombo = async function() {
    // 공통코드 설정
    const codeOptions = [{
        code: "STD_CD_APPL_CONTN_TP_CD", // 상품구분 콤보박스 조회
        firstRow : ["", "전체"],
        compID: "cmb_STD_CD_APPL_CONTN_TP_CD"
    }];

    await $c.data.setCommonCode(codeOptions);
};

/**
 * @method
 * @name setDefaultVal
 * @description 화면의 기본값 세팅
 * @returns {void}
 * @hidden N
 */
scwin.setDefaultVal = function() {
    const sToday = $c.date.getServerDateTime("yyyyMMdd");
    ipt_fromStdCdApplDd.setValue(sToday);
    ipt_toStdCdApplDd.setValue(sToday);

    txb_ISU_NM.focus();
};

/**
 * @method
 * @name chkValid
 * @description 사전체크
 * @param {String} pGubun 구분 코드
 * @returns {Promise<Boolean>}
 * @hidden N
 */
scwin.chkValid = async function(pGubun) {
    if (pGubun === "search") {
        const options = {
            validateType : "alert", // alert|mark|all
            checkType : "single", // single|multi
            fields : {
                ipt_fromStdCdApplDd : { required : true, name : "검색 시작일" },
                ipt_toStdCdApplDd : { required : true, name : "검색 종료일" }
            }
        };

        const validateResult = await $c.validate.validateDataCollect(tbl_search, options);
        if (!validateResult) {
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name getParam
 * @description 전달 값을 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {*}
 * @hidden N
 */
scwin.getParam = function (arrPar) {
    // ISIN 공통 팝업(ULDINS93300 등)이 opener 의 scwin.getParam(arrPar) 을 호출해 배열을 참조로 채우는 계약 — 인자가 없으면 scwin.arrPar 사용
    const out = Array.isArray(arrPar) ? arrPar : scwin.arrPar;
    out[0] = txb_param1.getValue(); // 표준코드 OR 발행기관 코드
    out[1] = txb_param2.getValue(); // 구분값
    return out;
};

/**
 * @method
 * @name customDateFormatter
 * @description 날짜 포매터
 * @param {*} data 셀 원본 값
 * @param {String} formattedData 포맷된 값
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @returns {*}
 * @hidden N
 */
scwin.customDateFormatter = function (data, formattedData, rowIndex, columnIndex) {
    if (!data) return "";

    const str = String(data).trim();

    // 14자리 이상인 경우 (밀리초 포함 17자리 등)
    if(str.length >= 14) {
        const yyyy = str.substring(0, 4);
        const MM = str.substring(4, 6);
        const dd = str.substring(6, 8);
        const hh = str.substring(8, 10);
        const mm = str.substring(10, 12);
        const ss = str.substring(12, 14);

        return yyyy + "-" + MM + "-" + dd + " " + hh + ":" + mm + ":" + ss;
    }

    // 8자리 날짜만 들어온 경우 예외 처리(yyyy-MM-dd)
    if(str.length === 8) {
        return str.substring(0,4) + "-" + str.substring(4,6) + "-" + str.substring(6, 8);
    }

    return data;
};

/**
 * @method
 * @name getDetailInfo
 * @description 상품구분코드별 상세조회 정보(API 명·상세 그리드/DataList 접미)를 돌려준다 — 08 은 상품구분 없음
 * @param {String} pGubun 상품구분코드
 * @returns {Object} { api } (미정의 구분이면 undefined)
 * @hidden N
 */
scwin.getDetailInfo = function (pGubun) {
    const detailMap = {
        "01" : { api : "autoChgSrchDetailBnd" },        // 채권
        "02" : { api : "autoChgSrchDetailStkcert" },    // 주권
        "03" : { api : "autoChgSrchDetailBenfcert" },   // 수익증권
        "04" : { api : "autoChgSrchDetailSubsrght" },   // 신주인수권증권
        "05" : { api : "autoChgSrchDetailSubsrght" },   // 신주인수권증서
        "06" : { api : "autoChgSrchDetailDr" },         // 유가증권예탁증서
        "07" : { api : "autoChgSrchDetailCp" },         // 전자단기사채/CP
        "09" : { api : "autoChgSrchDetailCd" },         // 양도성예금증서
        "10" : { api : "autoChgSrchDetailStkWrnt" },    // 주식워런트
        "11" : { api : "autoChgSrchDetailElsDls" },     // ELS/DLS
        "12" : { api : "autoChgSrchDetailEtn" },        // ETN
        "13" : { api : "autoChgSrchDetailInvest" }      // 투자계약증권
    };
    return detailMap[pGubun];
};

/**
 * @method
 * @name getDetailGubuns
 * @description 상세 그리드가 있는 상품구분코드 목록(01~07, 09~13)
 * @returns {Array} 상품구분코드 배열
 * @hidden N
 */
scwin.getDetailGubuns = function () {
    return ["01", "02", "03", "04", "05", "06", "07", "09", "10", "11", "12", "13"];
};

/**
 * @method
 * @name displayGrid
 * @description 상품구분에 따른 상세 그리드 표시 — 전체 숨긴 뒤 해당 구분의 그리드만 표시
 * @param {String} pGubun 상품구분코드
 * @returns {void}
 * @hidden N
 */
scwin.displayGrid = function (pGubun) {
    scwin.getDetailGubuns().forEach(function (gubun) {
        const grd = $p.getComponentById("grd_DtlList" + gubun);
        if (gubun === pGubun) grd.show(); else grd.hide();
    });
};

/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화 — 목록 조회(search)면 목록 DataList 까지, 그 외는 상세 DataList 만 비운다
 * @param {String} pGubun 호출 구분(search|searchDetail)
 * @returns {void}
 * @hidden N
 */
scwin.initDs = function (pGubun) {
    if (pGubun === "search") {
        dlt_searchList.removeAll();
    }
    scwin.getDetailGubuns().forEach(function (gubun) {
        $p.getComponentById("dlt_dtlList" + gubun).removeAll();
    });
};

/**
 * @method
 * @name openInsPopup
 * @description ISIN 공통 팝업(/ui/ins/common) 호출 — 결과가 있으면 코드/명 컴포넌트에 반영(AS-IS $c.cm.insPopupOpen 대체)
 * @param {*} cdObj 코드 값을 받을 컴포넌트(없으면 "")
 * @param {*} nmObj 명칭 값을 받을 컴포넌트(없으면 "")
 * @param {String} screenId 팝업 화면 ID
 * @param {String} title 팝업 제목
 * @param {String} width 팝업 너비
 * @param {String} height 팝업 높이
 * @returns {Promise<*>} 팝업 반환값
 * @hidden N
 */
scwin.openInsPopup = async function (cdObj, nmObj, screenId, title, width, height) {
    const options = {
        id : screenId,
        popupName : title,
        width : parseInt(width, 10) + 10,
        height : parseInt(height, 10) + 10
    };
    // 팝업(ULDINS93300 전환본 등)은 opener 의 scwin.getParam(arrPar) 을 직접 호출해 파라미터를 받는다 — data 는 참고용
    // TODO Stage2: ISIN 공통 팝업 반환 형태 확인 — AS-IS 는 팝업이 opener 의 js_ins_popup_cd/nm 컴포넌트에 직접 값을 설정
    const rtn = await $c.win.openPopup("/ui/ins/common/" + screenId + ".xml", options, { arrPar : scwin.getParam() });
    if (!$c.util.isEmpty(rtn)) {
        if (!$c.util.isEmpty(cdObj) && !$c.util.isEmpty(rtn.cd)) cdObj.setValue(rtn.cd);
        if (!$c.util.isEmpty(nmObj) && !$c.util.isEmpty(rtn.nm)) nmObj.setValue(rtn.nm);
    }
    return rtn;
};

/**
 * @method
 * @name delSpecialCharPartial
 * @description 입력값에서 ~ # & ' 문자를 제거한다(AS-IS $c.cm.delChar3 대체)
 * @param {Object} comp 입력 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.delSpecialCharPartial = function (comp) {
    const limitChar = /[~#&']/g;
    const value = comp.getValue();
    if (limitChar.test(value)) {
        comp.setValue(value.replace(limitChar, ""));
    }
};
